insert into messages (id,thread_id,sender_id,body,attachment_kind,attachment_log_id,attachment_date,attachment_uri,sent_at,read_at) values
('m-00001','th-c-001','t-001','Morning! Squat session today — keep bar speed crisp, stop 2 reps shy of failure.',null,null,null,null,'2026-08-25T09:24:00.000Z','2026-08-25T10:10:00.000Z'),
('m-00002','th-c-001','c-001','Done. Felt smooth, added 2.5kg on the top set.','workout','wl-00044',null,null,'2026-08-25T18:56:00.000Z','2026-08-25T19:03:00.000Z'),
('m-00003','th-c-001','t-001','Love that. Protein is drifting low on weekends though, have a look.','nutrition',null,'2026-08-25',null,'2026-08-26T08:05:00.000Z','2026-08-26T09:37:00.000Z'),
('m-00004','th-c-001','c-001','Fair. Ill front-load it Saturday.',null,null,null,null,'2026-08-26T20:58:00.000Z','2026-08-26T21:50:00.000Z'),
('m-00005','th-c-001','t-001','Check-in form is open — send it over before tonight?',null,null,null,null,'2026-08-28T07:41:00.000Z','2026-08-28T08:20:00.000Z'),
('m-00006','th-c-001','t-001','Nice streak this week 👏 Keep dinner logged and youre golden.',null,null,null,null,'2026-08-29T08:47:00.000Z',null),
('m-00007','th-c-002','c-002','Struggling with the 1780 target, Im starving by 4pm.',null,null,null,null,'2026-08-23T10:03:00.000Z','2026-08-23T11:38:00.000Z'),
('m-00008','th-c-002','t-001','Lets move 200 kcal from breakfast to an afternoon snack. Try it for a week.',null,null,null,null,'2026-08-23T11:47:00.000Z','2026-08-23T12:36:00.000Z'),
('m-00009','th-c-002','c-002','Much better this week, thank you!',null,null,null,null,'2026-08-27T19:30:00.000Z','2026-08-27T20:34:00.000Z'),
('m-00010','th-c-002','c-002','Quick one — can I swap Thursday to Friday?',null,null,null,null,'2026-08-29T09:43:00.000Z',null),
('m-00011','th-c-003','t-001','Programme for the week is up — same structure, small jump on the main lifts.',null,null,null,null,'2026-08-25T09:02:00.000Z','2026-08-25T10:12:00.000Z'),
('m-00012','th-c-003','c-003','Got it, thanks!',null,null,null,null,'2026-08-25T18:48:00.000Z','2026-08-25T19:38:00.000Z'),
('m-00013','th-c-003','t-001','Solid week. Keep it rolling.',null,null,null,null,'2026-08-28T08:52:00.000Z',null),
('m-00014','th-c-004','t-001','Havent seen a log since last Tuesday — everything okay?',null,null,null,null,'2026-08-20T12:57:00.000Z','2026-08-20T13:31:00.000Z'),
('m-00015','th-c-004','t-001','Checking in again. Even a rough estimate of meals helps me help you.',null,null,null,null,'2026-08-27T21:15:00.000Z','2026-08-27T22:35:00.000Z'),
('m-00016','th-c-004','t-001','Ive dropped your sessions to 3 a week to make it easier to stick to.',null,null,null,null,'2026-08-29T07:19:00.000Z',null),
('m-00017','th-c-005','c-005','That was brutal — barely finished the carries.','workout','wl-00096',null,null,'2026-08-26T20:15:00.000Z','2026-08-26T21:27:00.000Z'),
('m-00018','th-c-005','t-001','Third hard session in a row. Deloading you next week.',null,null,null,null,'2026-08-26T21:49:00.000Z','2026-08-26T22:12:00.000Z'),
